mapper.insert:

      SELECT NVL(MAX(STATION_NO), 0) + 1 FROM TB_STATION

  INSERT
    INTO 
    	   TB_STATION 
    	   (
         STATION_NO
       , STATION_NAME
       , STATION_ADDRESS
       , STATION_TYPE
       , STATION_LNG
       , STATION_LAT
       , REGISTER_DATE
       , STATUS
       , STATION_COUNT
       , USEABLE_STATION
  	 ) 
VALUES (
       #{stationNo}
     , #{stationName}
     , #{stationAddress}
     , #{stationType}
     , #{stationLng}
     , #{stationLat}
     , SYSDATE
     , NVL(#{status}
     , 'Y'
       )
     , #{stationCount}
     , #{useableStation}
  )

mapper.update:
UPDATE TB_STATION
SET STATUS = 'N'
WHERE STATION_NO = #{stationNo}

mapper.insert:

    SELECT NVL(MAX(REVIEW_NO), 0) + 1 FROM TB_REVIEW

INSERT INTO TB_REVIEW (
    REVIEW_NO, STATION_NO, REVIEW_TITLE, REVIEW_CONTENT, 
    STATUS, REVIEW_DATE, MEMBER_NO
) VALUES (
    #{reviewNo}, #{stationNo}, #{reviewTitle}, #{reviewContent}, 
    NVL(#{status}, 'Y'), SYSDATE, #{memberNo}
)

mapper.update:
UPDATE TB_REVIEW
SET REVIEW_TITLE = #{reviewTitle},
    REVIEW_CONTENT = #{reviewContent}
WHERE REVIEW_NO = #{reviewNo}
AND STATUS = 'Y'

UPDATE TB_REVIEW
SET STATUS = 'N'
WHERE REVIEW_NO = #{reviewNo}
